import { cn } from '@cascivo/core/pure'
import type { ReactNode } from 'react'
import styles from './dashboard-layout.module.css'

export interface DashboardLayoutProps {
  stats?: ReactNode
  main: ReactNode
  aside?: ReactNode
  className?: string | undefined
}

export function DashboardLayout({ stats, main, aside, className }: DashboardLayoutProps) {
  return (
    <div className={cn(styles['layout'], className)}>
      {stats && <div className={styles['stats']}>{stats}</div>}
      <div className={styles['body']}>
        <div className={styles['main']}>{main}</div>
        {aside && <div className={styles['aside']}>{aside}</div>}
      </div>
    </div>
  )
}

@layer cascivo.component {
  .layout {
    display: flex;
    flex-direction: column;
    gap: var(--cascivo-space-6);
    container-type: inline-size;
  }

  .stats {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr));
    gap: var(--cascivo-space-4);
  }

  .body {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 20rem;
    gap: var(--cascivo-space-6);
    align-items: start;

    @container (max-width: 56rem) {
      grid-template-columns: 1fr;
    }
  }

  .main {
    min-inline-size: 0;
  }

  .aside {
    min-inline-size: 0;
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'DashboardLayout',
  description: 'Dashboard page layout with stats strip, main content area, and optional aside.',
  category: 'layout',
  clientJs: 'none',
  states: [],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'stats',
      type: 'ReactNode',
      required: false,
      description: 'Stats/KPI row (auto-fit grid)',
    },
    { name: 'main', type: 'ReactNode', required: true, description: 'Main content area' },
    {
      name: 'aside',
      type: 'ReactNode',
      required: false,
      description: 'Optional aside panel (20rem)',
    },
  ],
  tokens: ['--cascivo-space-4', '--cascivo-space-6'],
  accessibility: { role: 'generic', wcag: '2.1-AA', keyboard: [] },
  examples: [
    {
      title: 'With stats',
      code: '<DashboardLayout stats={<div>KPIs</div>} main={<div>Content</div>} />',
      description: 'Stats + main layout',
    },
  ],
  dependencies: ['@cascivo/core'],
  tags: ['layout', 'dashboard', 'page'],
  intent: {
    whenToUse: [
      'A dashboard page with a stats strip, main content area, and optional aside',
      'Composing KPI tiles and charts into a standard analytics layout',
